      primary_cta_visit_code,
      started_at, snapshot_date, end_date
    ) VALUES (
      'sonic-airdrop-s2', 'Sonic Labs Points Season 2', 'S', NULL, 'Sonic''s S2 points program rewards activity on its high-speed EVM chain. Snapshot mid-September.',
      'Following S1''s $250M+ distribution, Sonic Labs has opened Season 2 of its points program. Points are earned for bridging assets, providing liquidity in whitelisted Sonic Gateway pools, and using Sonic-native dapps (SwapX, Beethoven X, Silo Finance V2). The S2 conversion ratio has been pre-announced at 200 points = 1 S token, with a hard cap on per-wallet allocations to combat sybils. Activity from S1 is not carried over — wallets must accrue fresh S2 points.', '- Bridge to Sonic via the official Gateway
- Accumulate points by holding stablecoins (1 pt / $ / day) or whitelisted LPs (2.5 pts / $ / day)
- Use SwapX or Beethoven X for at least 3 swaps per week
- Minimum 50,000 points required to qualify', '1. Bridge ETH or USDC to Sonic via https://gateway.soniclabs.com.
2. Park balance in a points-eligible vault — staked S, Silo USDC vault, etc.
3. Add LP on SwapX for the highest per-dollar rate.
4. Track your points via the official dashboard.
5. Snapshot is September 15, 2026 — keep position live until then.
6. Tokens will be claimable via the same dashboard 1-2 weeks after snapshot.',
      'live',
      (SELECT id FROM chains WHERE slug = 'ethereum' LIMIT 1),
      (SELECT id FROM categories WHERE slug = 'points' LIMIT 1),
      (SELECT id FROM sources WHERE slug = 'editorial' LIMIT 1),
      0, 0,
      150, 4000, 76,
      'https://sonic.fan', 'https://x.com/0xSonicLabs', NULL,
      'esrMVhyB',
      '2026-04-01', '2026-09-15', '2026-09-30'
    ) ON DUPLICATE KEY UPDATE
