INSERT INTO visit_codes (code, target_url, airdrop_id, source_label) VALUES ('esrMVhyB', 'https://sonic.fan', (SELECT id FROM airdrops WHERE slug = 'sonic-airdrop-s2' LIMIT 1), 'primary') ON DUPLICATE KEY UPDATE target_url=VALUES(target_url), airdrop_id=VALUES(airdrop_id);
